import{_ as d,C as e,o as c,c as g,j as a,a as u,G as t,a2 as n}from"./chunks/framework.BgSoyxN5.js";const w=JSON.parse('{"title":"Партнёрство с TickerForge | Исследования, рыночные новости и инструменты для Telegram","description":"Партнёрство с TickerForge: исследовательские блоки для Telegram, автоматические посты рыночной аналитики, диагностика портфеля, отслеживаемые ссылки и измеримые пилотные кампании.","frontmatter":{"title":"Партнёрство с TickerForge | Исследования, рыночные новости и инструменты для Telegram","description":"Партнёрство с TickerForge: исследовательские блоки для Telegram, автоматические посты рыночной аналитики, диагностика портфеля, отслеживаемые ссылки и измеримые пилотные кампании.","aside":false,"locale":"ru","alternateLocales":{"en":"/partners","ru":"/ru/partners"},"pageClass":"partners-page partner-hub-page"},"headers":[],"relativePath":"ru/partners.md","filePath":"ru/partners.md","lastUpdated":1788410450000}'),h={name:"ru/partners.md"},m={class:"partners-wide"};function _(f,r,T,b,v,k){const s=e("PartnerPageAnalytics"),i=e("PartnerChannelCta"),o=e("PartnerCabinetCta"),p=e("PartnerReferralCta"),l=e("PartnerLeadForm");return c(),g("div",null,[r[0]||(r[0]=a("h1",{id:"партнерство-с-tickerforge",tabindex:"-1"},[u("Партнёрство с TickerForge "),a("a",{class:"header-anchor",href:"#партнерство-с-tickerforge","aria-label":'Permalink to "Партнёрство с TickerForge"'},"​")],-1)),r[1]||(r[1]=a("p",null,"Исследовательские инструменты, автоматическая рыночная аналитика и диагностика портфеля для финансовых авторов — в Telegram, Instagram, YouTube, TikTok, LinkedIn, в рассылке или на своём сайте.",-1)),r[2]||(r[2]=a("p",null,"TickerForge помогает авторам и сообществам добавить в материалы структурный рыночный контекст, диагностику по акциям, проверку здоровья портфеля и автоматические исследовательские посты — без создания собственного финтех-продукта. Если вы пишете о рынках где угодно и аудитория доверяет вам настолько, чтобы кликать, программа для вас: площадка не является условием.",-1)),r[3]||(r[3]=a("p",null,"Начните с малого: один пост, одна отслеживаемая ссылка, один измеримый пилот.",-1)),t(s,{offer:"hub",locale:"ru"}),r[4]||(r[4]=a("div",{class:"partners-hero-actions"},[a("a",{class:"partners-button partners-button--primary",href:"#partner-options"},"Посмотреть варианты партнёрства"),a("a",{class:"partners-button partners-button--secondary",href:"#partner-contact"},"Предложить пилот")],-1)),t(i,{eyebrow:"Посмотрите вживую",title:"Сначала почитайте посты в канале",text:"Все форматы с этих страниц уже выходят в публичном канале TickerForge. Откройте его, пролистайте последние две недели и решите, подходит ли такой контент вашей аудитории.",cta:"Открыть канал TickerForge"}),r[5]||(r[5]=n('<p class="partners-locale-switch"><a href="/partners" hreflang="en" data-partner-event="cta" data-partner-option="locale_en" data-analytics-placement="partner_locale_switch">Read this page in English</a></p><div class="partners-wide partners-routing-note"><p><strong>Ищете конкретный формат?</strong> У каждого направления своя страница со своими форматами контента: исследования по компаниям, рыночный и макро-контент или диагностика портфеля.</p><a class="partners-button partners-button--secondary" href="#partner-options">Посмотреть три направления</a></div><p>TickerForge — образовательное программное обеспечение для поддержки решений. Это не инвестиционная рекомендация, не сигнальный канал, не брокер и не обещание доходности.</p><h2 id="partner-options" tabindex="-1">Варианты партнёрства <a class="header-anchor" href="#partner-options" aria-label="Permalink to &quot;Варианты партнёрства {#partner-options}&quot;">​</a></h2><p>У каждого направления своя страница, свой формат пилота и свой способ измерить результат. Выберите то, что ближе к тому, как уже работает ваш канал или сообщество.</p><div class="partners-wide"><div class="partners-option-grid"><a class="partners-option" href="/ru/partners/stock-analysis-and-ideas" data-partner-event="option" data-partner-option="telegram_research" data-analytics-placement="partner_hub_options"><span>Слой исследований</span><strong>Исследовательский слой для Telegram</strong><p>Добавляйте в свои посты блоки TickerForge: вердикт по акции, активность инсайдеров, движения фондов и идеи по акциям.</p><p><strong>Кому подходит:</strong></p><ul class="partners-option-best"><li>финансовым Telegram-каналам</li><li>авторам разборов по акциям</li><li>сообществам, где обсуждают тикеры</li><li>тем, кто хочет усилить аргументацию в постах</li></ul><span class="partners-option-cta">Открыть страницу</span></a><a class="partners-option" href="/ru/partners/market-news" data-partner-event="option" data-partner-option="market_news" data-analytics-placement="partner_hub_options"><span>Регулярный контент</span><strong>Автоматические рыночные новости</strong><p>Используйте ежедневные и еженедельные посты рыночной аналитики TickerForge как регулярный контент канала.</p><p><strong>Кому подходит:</strong></p><ul class="partners-option-best"><li>каналам, которым нужны стабильные рыночные апдейты</li><li>сообществам, которым нужен ежедневный или недельный контекст риска</li><li>авторам, которым нужны сводки по режиму, стрессу и ротации секторов</li></ul><span class="partners-option-cta">Открыть страницу</span></a><a class="partners-option" href="/ru/partners/portfolio-health" data-partner-event="option" data-partner-option="portfolio_health" data-analytics-placement="partner_hub_options"><span>Диагностика портфеля</span><strong>Здоровье портфеля</strong><p>Дайте аудитории проверить концентрацию, отраслевую структуру, денежную подушку и устойчивость к стрессу на своих позициях.</p><p><strong>Кому подходит:</strong></p><ul class="partners-option-best"><li>авторам, которые пишут про портфели</li><li>консультантам</li><li>сообществам с инвестиционными портфелями</li><li>для разговора про ко-брендинг и white-label</li></ul><span class="partners-option-cta">Открыть страницу</span></a></div></div><p>На каждой странице перечислены форматы контента этого направления, а форма внизу этой страницы принимает тот же выбор: одно направление плюс форматы, которые вам интересны.</p>',7)),t(o,{locale:"ru"}),r[6]||(r[6]=n('<h2 id="partner-access" tabindex="-1">🎁 Что получает партнёр <a class="header-anchor" href="#partner-access" aria-label="Permalink to &quot;🎁 Что получает партнёр {#partner-access}&quot;">​</a></h2><p>Некоторые пилоты включают временный партнёрский доступ к TickerForge на время активной коллаборации. Это касается не только Telegram: владелец LinkedIn-группы, YouTube-автор, Instagram-блогер про финансы, автор рассылки или оператор сообщества может использовать продукт для подготовки более сильных материалов и вести заинтересованную аудиторию по отслеживаемым ссылкам.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>⭐ Доступ Standard.</strong> TickerForge Standard на согласованное окно пилота — посты строятся на полном исследовательском слое, а не на бесплатном превью.</li><li><strong>🧰 Партнёрский кабинет.</strong> Ваше рабочее место внутри бота: выбрали формат, нажали кнопку — получили готовый пост со своей ссылкой внутри. Там же язык постов, статистика и месячный отчёт. <a href="/ru/partners/cabinet">Как он устроен</a>.</li><li><strong>🧠 Готовый контент под ваш формат.</strong> Не сырые данные, вокруг которых надо писать, — а готовый пост на живых данных в нужной форме. Stock Verdict, активность инсайдеров, движения фондов, еженедельные идеи, рыночный режим и экономическое здоровье США — по запросу, в одно нажатие.</li><li><strong>🔗 Отслеживаемые ссылки.</strong> Каждый партнёрский пост несёт вашу ссылку внутри собственного призыва к действию и ведёт читателя сразу в нужный сценарий TickerForge.</li><li><strong>💰 Реферальный доход.</strong> До <strong>20% каждый месяц</strong> от того, что платят пришедшие от вас люди, пока их подписка активна, — по тем же правилам, что и <a href="/ambassador">/ambassador</a>. Без ограничений по числу рефералов и по сумме в месяц.</li><li><strong>📊 Измеримый результат.</strong> Сгенерированные посты, запуски бота по каждому формату, рефералы и оценка заработка — в Партнёрском кабинете.</li></ul></div><h2 id="formats" tabindex="-1">В каких форматах можно публиковать <a class="header-anchor" href="#formats" aria-label="Permalink to &quot;В каких форматах можно публиковать {#formats}&quot;">​</a></h2><p>Partner Cabinet генерирует пост как текст плюс вашу отслеживаемую ссылку. Это контейнер, который нужен Telegram, — и все остальные контейнеры строятся на том же самом посте с той же ссылкой. Скажите, какой нужен вам, и он поднимется в очереди.</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Доступно сейчас</span><strong>Пост в Telegram</strong><p>Форматированный текст с картинкой и вашей ссылкой внутри. Генерируется в одно нажатие, пересылается как есть.</p></div><div class="partners-format"><span>По запросу под пилот</span><strong>Пост на веб-странице</strong><p>Тот же сгенерированный пост блоком для вашего сайта, блога или платформы рассылок — со ссылкой на веб-сценарий, а не на бота.</p></div><div class="partners-format"><span>По запросу под пилот</span><strong>Веб-виджет</strong><p>Встраиваемый живой блок, который обновляется сам, — вместо поста, который надо перевыпускать каждую неделю.</p></div><div class="partners-format"><span>Ожидается</span><strong>Email</strong><p>Тот же пост под рассылку, чтобы автор, публикующийся почтой, не был вынужден уходить в мессенджер.</p></div><div class="partners-format"><span>Ожидается</span><strong>RSS-лента</strong><p>Лента, которую заберёт ваша автоматизация и положит туда, где вас уже читают.</p></div></div></div><p>Формата нет в списке — всё равно спросите. Это перечень того, что есть и что в очереди, а не предел того, во что можно упаковать сгенерированный пост.</p><h2 id="partner-requirements" tabindex="-1">Что мы просим взамен <a class="header-anchor" href="#partner-requirements" aria-label="Permalink to &quot;Что мы просим взамен {#partner-requirements}&quot;">​</a></h2><p>Партнёрский доступ — это обмен, а не подарок. Коротко:</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Аудитория:</strong> от 1 000 живых подписчиков на площадке, где вы публикуетесь, тематика — финансы и инвестиции. Меньшие, но сильно вовлечённые сообщества рассматриваются индивидуально.</li><li><strong>Публикации:</strong> стандартный пилот — 3 качественных поста за 30 дней; дальше обычный ритм 2–4 качественных поста в месяц.</li><li><strong>Качественный пост:</strong> реальная проверка TickerForge, ваш голос, понятный образовательный дисклеймер и отслеживаемая ссылка. Засчитываются только опубликованные посты, которые мы можем подтвердить.</li><li><strong>Раскрытие связи:</strong> рекламный, affiliate-supported или подготовленный с помощью бесплатного доступа контент партнёр раскрывает явно.</li><li><strong>Личное место:</strong> доступ одобряется индивидуально, ограничен по времени и не передаётся. Если согласованный ритм останавливается — доступ ставится на паузу.</li></ul></div><div class="partners-wide partners-routing-note"><p><strong>Полные условия участия, обязательства и точные причины, по которым доступ заканчивается,</strong> вынесены на отдельную страницу, чтобы эта оставалась читаемой.</p><a class="partners-button partners-button--secondary" href="/ru/partners/what-you-get" data-partner-event="cta" data-partner-option="what_you_get" data-analytics-placement="partner_hub_what_you_get">Что даём мы</a><a class="partners-button partners-button--secondary" href="/ru/partners/requirements" data-partner-event="cta" data-partner-option="requirements" data-analytics-placement="partner_hub_requirements">Открыть требования к партнёрам</a></div><p>Pro-доступ, bulk API, кастомные фиды, ко-брендинговые отчёты и white-label в пилот не входят — это отдельные коммерческие разговоры.</p><h2 id="как-проходит-партнерскии-пилот" tabindex="-1">Как проходит партнёрский пилот <a class="header-anchor" href="#как-проходит-партнерскии-пилот" aria-label="Permalink to &quot;Как проходит партнёрский пилот&quot;">​</a></h2><div class="partners-wide partners-wide--timeline"><div class="partners-steps"><div><span>1</span><strong>Выбрать направление</strong><p>Анализ акций и идеи, автоматические рыночные новости или портфельная диагностика.</p></div><div><span>2</span><strong>Провести один тест</strong><p>Опубликовать один пост или прогнать один короткий контент-тест. Для старта интеграция не нужна.</p></div><div><span>3</span><strong>Использовать отслеживаемые ссылки</strong><p>Отслеживаемые ссылки или deep link в бот связывают пост с тем, что происходит дальше.</p></div><div><span>4</span><strong>Измерить</strong><p>Клики, запуски бота, проверки акций, импорты портфелей, email, комментарии и интерес к платным планам.</p></div><div><span>5</span><strong>Решить</strong><p>Повторить, сделать рекламный формат, партнёрскую программу, ко-брендинг — или остановиться.</p></div></div></div>',14)),t(p,{eyebrow:"Реферальная программа",title:"Зарабатывайте на рекомендациях параллельно с пилотом",text:"Ambassador Program платит 20% от каждой платной подписки каждый месяц, пока приведённый пользователь остаётся активным. Это работает вместе с партнёрским пилотом: одна и та же аудитория может прийти по вашей отслеживаемой ссылке и оформить подписку по вашей реферальной.",note:"Страница программы пока доступна только на английском.",cta:"Посмотреть Ambassador Program"}),r[7]||(r[7]=n('<h2 id="чем-tickerforge-не-является" tabindex="-1">Чем TickerForge не является <a class="header-anchor" href="#чем-tickerforge-не-является" aria-label="Permalink to &quot;Чем TickerForge не является&quot;">​</a></h2><div class="partners-wide partners-wide--not"><p>TickerForge — это не:</p><ul><li>торговый робот</li><li>сигнальный канал</li><li>брокер</li><li>система копирования сделок</li><li>обещание прибыли</li><li>персональная инвестиционная рекомендация</li></ul><p>TickerForge — образовательное ПО для поддержки решений: оно помогает посмотреть на акцию, портфель, структуру владения и рыночный контекст до того, как действовать.</p></div><h2 id="partner-contact" tabindex="-1">Предложить партнёрский пилот <a class="header-anchor" href="#partner-contact" aria-label="Permalink to &quot;Предложить партнёрский пилот {#partner-contact}&quot;">​</a></h2><p>Расскажите, какое направление вам интересно и как устроен ваш канал. Полезные детали: ссылка на канал или сообщество, размер аудитории, язык, интересующий формат партнёрства, желаемый первый тест и хотите ли вы обсудить рекламный пост, партнёрскую программу или контент-коллаборацию.</p>',4)),a("div",m,[t(l,{locale:"ru",source:"partners_hub"})]),r[8]||(r[8]=n('<h2 id="смотрите-также" tabindex="-1">Смотрите также <a class="header-anchor" href="#смотрите-также" aria-label="Permalink to &quot;Смотрите также&quot;">​</a></h2><ul><li><a href="/ru/partners/what-you-get">Что мы даём партнёру</a></li><li><a href="/ru/partners/requirements">Требования к партнёрам</a></li><li><a href="/ru/partners/cabinet">Как работает Partner Cabinet</a></li><li><a href="/ru/partners/stock-analysis-and-ideas">Партнёрство: исследования в Telegram</a></li><li><a href="/ru/partners/market-news">Партнёрство: рыночные новости</a></li><li><a href="/ru/partners/portfolio-health">Партнёрство: здоровье портфеля</a></li><li><a href="/import-portfolio">Проверка здоровья портфеля</a></li><li><a href="/stock-widget">Виджет проверки акции</a></li><li><a href="/market-widget">Виджет рыночного режима</a></li><li><a href="/ambassador">Реферальная программа Ambassador</a></li><li><a href="/pricing">Тарифы TickerForge</a></li></ul>',2))])}const q=d(h,[["render",_]]);export{w as __pageData,q as default};
